export interface TieAtomicActivity {
  code: string;
  title: string;
  mainComp: string;
  specComp: string;
  mainAct: string;
  specActs: string[];
  periods: number;
  methods: string;
  resources: string;
  assessment: string;
}

export interface TieFormSyllabus {
  ppw: number;
  orient: boolean;
  book: string;
  activities: TieAtomicActivity[];
}

export type TieSubjectKey =
  | 'COMPUTER SCIENCE'
  | 'BASIC MATHEMATICS'
  | 'ADDITIONAL MATHEMATICS'
  | 'CHEMISTRY'
  | 'GEOGRAPHY'
  | 'HISTORY'
  | 'BUSINESS STUDIES'
  | 'BOOK-KEEPING';

export type TieFormKey = 'FORM ONE' | 'FORM TWO' | 'FORM THREE' | 'FORM FOUR';

export type TieSyllabiDatabase = Record<
  TieSubjectKey,
  Partial<Record<TieFormKey, TieFormSyllabus>>
>;

export const TIE_SUBJECT_OPTIONS: { key: TieSubjectKey; label: string }[] = [
  { key: 'COMPUTER SCIENCE', label: 'Computer Science (Form I – IV)' },
  { key: 'BASIC MATHEMATICS', label: 'Basic Mathematics (Form I – IV)' },
  { key: 'ADDITIONAL MATHEMATICS', label: 'Additional Mathematics (Form III – IV)' },
  { key: 'CHEMISTRY', label: 'Chemistry (Form I – IV)' },
  { key: 'GEOGRAPHY', label: 'Geography (Form I – IV)' },
  { key: 'HISTORY', label: 'History (Form I – IV)' },
  { key: 'BUSINESS STUDIES', label: 'Business Studies (Form I – IV)' },
  { key: 'BOOK-KEEPING', label: 'Book-keeping (Form I – IV)' },
];

// Helper to build atomic activity objects cleanly
function A(
  code: string,
  title: string,
  mainComp: string,
  specComp: string,
  mainAct: string,
  specActs: string[],
  periods: number,
  methods: string,
  resources: string,
  assessment: string
): TieAtomicActivity {
  return {
    code,
    title,
    mainComp,
    specComp,
    mainAct,
    specActs,
    periods,
    methods,
    resources,
    assessment,
  };
}

