export function mapElimikaContextToTie(
  cls?: string,
  subject?: string
): { subject: TieSubjectKey; form: TieFormKey } {
  const s = (subject || '').toUpperCase().trim();
  let mappedSubj: TieSubjectKey = 'COMPUTER SCIENCE';

  if (s.includes('ADDITIONAL') && s.includes('MATH')) {
    mappedSubj = 'ADDITIONAL MATHEMATICS';
  } else if (s.includes('MATH')) {
    mappedSubj = 'BASIC MATHEMATICS';
  } else if (s.includes('CHEM')) {
    mappedSubj = 'CHEMISTRY';
  } else if (s.includes('GEO')) {
    mappedSubj = 'GEOGRAPHY';
  } else if (s.includes('HIST')) {
    mappedSubj = 'HISTORY';
  } else if (s.includes('BUSINESS') || s.includes('COMMERCE')) {
    mappedSubj = 'BUSINESS STUDIES';
  } else if (s.includes('BOOK') || s.includes('ACCOUNT')) {
    mappedSubj = 'BOOK-KEEPING';
  } else if (s.includes('COMPUTER') || s.includes('ICS') || s.includes('ICT')) {
    mappedSubj = 'COMPUTER SCIENCE';
  }

  const c = (cls || '').toUpperCase().trim();
  let mappedForm: TieFormKey = 'FORM ONE';
  if (c.includes('4') || c.includes('FOUR') || c.includes('IV')) mappedForm = 'FORM FOUR';
  else if (c.includes('3') || c.includes('THREE') || c.includes('III')) mappedForm = 'FORM THREE';
  else if (c.includes('2') || c.includes('TWO') || c.includes('II')) mappedForm = 'FORM TWO';
  else mappedForm = 'FORM ONE';

  const availableForms = Object.keys(ALL_SYLLABI[mappedSubj]) as TieFormKey[];
  if (!availableForms.includes(mappedForm)) {
    mappedForm = availableForms[0] || 'FORM THREE';
  }

  return { subject: mappedSubj, form: mappedForm };
}
